// Episodic releases: a series item with a `release` date stays locked until that day,
// so a series can drop weekly. Items with no date are always available.
export const itemOut = (e) => !e.release || Date.parse(e.release) <= Date.now();
export const itemOutWhen = (e) => (e.release ? new Date(e.release) : null);
export const daysUntilOut = (e) => (e.release ? Math.max(0, Math.ceil((new Date(e.release) - Date.now()) / 864e5)) : 0);
