export async function addSeriesItem(series, e) {
  const have = getItem(e.id);
  if (have) return have;
  const base = { id: e.id, type: "book", title: e.title, series: series.title, author: { blackwood: "Blackwood University", incarnate: "Incarnate", backrooms: "Backrooms" }[series.id] || series.title, cover: e.cover,
    description: e.blurb, origin: "Kitsune Original series", credit: { creator: series.title, license: series.rights }, tags: ["kitsune originals", series.id, ...(series.mature ? ["mature"] : [])],
    status: "unread", rating: 0, added: Math.floor(Date.now() / 1000), lang: "en" };
  if (e.kind === "script") return saveItem({ ...base, source: { kind: "script", file: e.file, credit: `${series.title} · ${e.label} · ${series.rights}` } });
  const r = await fetch(e.file);
  if (!r.ok) throw new Error("That book didn't load. Check your connection and try again.");
  return saveItem({ ...base, source: { kind: "text", text: await r.text() } });
}

// Add an original to the library (stories are stored whole, so they read offline straight away).
export async function addOriginal(o) {
  const have = getItem(o.id);
  if (have) return have;
  const base = { id: o.id, type: o.type, title: o.title, author: "Kitsune Originals", cover: o.cover, description: o.blurb,
    origin: "Kitsune Original", credit, tags: ["kitsune originals"], status: "unread", rating: 0, added: Math.floor(Date.now() / 1000) };
  if (o.type === "manga") return saveItem({ ...base, series: o.series, volume: o.volume, pages: o.pages, dir: "ltr", source: { kind: "urls", urls: o.urls } });
  const r = await fetch(o.file);
  if (!r.ok) throw new Error("That story didn't load. Check your connection and try again.");
  const text = (await r.text()).replace(/^.*\n+A Kitsune Original\..*\n+/, ""); // the title and licence line live in the item's details instead
  return saveItem({ ...base, lang: "en", source: { kind: "text", text } });
}

