// Add a classic and (optionally) download its text so it reads offline.
export async function addClassic(id, title, { offline = false } = {}) {
  let item = getItem("gb-" + id);
  if (!item) {
    let b = null;
    try { b = await api(`books/${id}`); } catch {}
    item = await saveItem({
      id: "gb-" + id, type: "book", title: b?.title || title, author: (b?.authors || []).join(", "), cover: b?.cover || `https://www.gutenberg.org/cache/epub/${id}/pg${id}.cover.medium.jpg`,
      description: b?.summary || "", source: { kind: "gutenberg", gid: id }, origin: "Project Gutenberg", tags: ["free classics"], status: "unread", rating: 0, added: Math.floor(Date.now() / 1000),
    });
  }
  if (offline && !item.source.cachedText) {
    item.source.cachedText = await api(`books/${id}/text`);
    await saveItem(item);
  }
  return item;
}
